#!/usr/bin/env python3
"""Round 2 sheets -> tools/art/jobs_cards_r2.json.  Same STYLE_V1 anchor (imported) plus a print-grain addendum
(critic r1: prints read as clean vector stickers) and a 2nd reference = an r1 sheet, so new cards match the kit.
Targets the r1 critic gaps: separate layered hill strips for mid/back rows, varied wheat patches + stooks,
plank bridge / stepping stones / ducks, big foreground hero plants, more variants of the common trees."""
import json, sys
sys.path.insert(0, "/Users/house_of_4k2b/orca/popup-atlas/tools/art")
from mk_jobs_cards import STYLE_V1, ROOT, RAW

REF = [f"{ROOT}/art_src/cards/refs/sw_trav_walk.png", f"{RAW}/sh_trees_green.png"]
GRAIN = """PRINT TEXTURE (v2 addendum): the printed detail looks hand-pulled like a lino / risograph print on matte cardstock — slightly grainy ink with tiny speckles, very slight colour misregistration of the printed lines, soft paper tooth visible in flat areas. Not clean vector art."""


def job(id_, subject, aspect="landscape 3:2"):
    return {"id": id_, "kind": "sprite", "pass": 2, "aspect": aspect, "out": f"{RAW}/{id_}.png", "refs": REF,
            "prompt": STYLE_V1 + "\n" + GRAIN + "\nReference 1 = paper material, palette family and friendliness only (do not draw the character). Reference 2 = an existing card sheet of this kit: match its printing style, rim and palette exactly, but draw NEW objects (do not copy its trees).\n\nSUBJECT: " + subject}


J = [
    job("sh2_hills_layer_a", "a sheet of 3 separate very wide single-layer hill cards stacked one above the other with wide magenta gaps between them; each card is ONE rolling hill ridge silhouette (wider than 4:1), with a gently curved top edge and a straight flat bottom edge along its full width: (1) moss green hill with printed hedgerow rows and tiny round tree silhouettes on the ridge, (2) sage green hill with stitched field-boundary lines and stamped dot flowers, (3) olive green hill with a printed row of small poplars and scalloped grass motifs."),
    job("sh2_hills_layer_b", "a sheet of 3 separate very wide single-layer hill cards stacked one above the other with wide magenta gaps between them; each card is ONE rolling hill ridge silhouette (wider than 4:1) with a straight flat bottom edge along its full width: (1) mustard ochre wheat-field hill with printed furrow stripes and tiny sheaves, (2) terracotta ploughed hill with printed curved furrow lines and a little hedge, (3) far soft blue-green ridge with a row of tiny printed conifer silhouettes and faint hatching."),
    job("sh2_hills_wooded", "a sheet of 2 separate wide back-row cards side by side with a wide magenta gap: (1) a rounded hill crowned with a dense grove of round-canopy trees in green, ochre and terracotta, printed leaf veins, all one connected silhouette, (2) a long low hill with a line of fir trees and a tiny cottage silhouette printed on its slope. Each has a straight flat bottom edge along its full width."),
    job("sh2_wheat_patch", "a sheet of 6 separate wheat-field cards of clearly different widths and heights: (1) a short wide clump of golden wheat, (2) a tall narrow clump of wheat with heavy ears, (3) a broken ragged wheat patch with gaps and a few red poppies, (4) a small group of 5 loose wheat stalks, (5) a wheat stook: three tied sheaves leaning together, (6) a medium wheat clump in paler cream-gold. Printed wheat ears and stem lines. Each grows from a straight flat bottom edge."),
    job("sh2_hay_farm", "a sheet of 6 separate farm cards: a square hay bale with printed straw strokes and twine, a stack of three square bales, a tall haystack with a wooden pole on top, a small wooden hay cart loaded with hay (side view, wooden wheel), a neat stacked woodpile of round log ends, a leaning wooden ladder against nothing (just the ladder). Each with a straight flat bottom edge."),
    job("sh2_water", "a sheet of 6 separate stream cards: a small flat wooden plank footbridge seen from the side with thick visible plank ends and two short posts (much wider than tall), a row of 4 rounded stepping stones (wide and low), a cream duck swimming (only the body above a short teal ripple band), a brown duck swimming on a teal ripple band, a clump of lily pads with one pink-cream water lily seen from the side on a ripple band, a little wooden jetty with posts. Each with a straight flat bottom edge."),
    job("sh2_trees_green_b", "a sheet of 4 separate NEW round-canopy deciduous tree cards in greens: (1) big lumpy three-lobed canopy in deep moss green with printed oak-leaf motifs, (2) tall egg-shaped canopy in fresh spring green with printed chevron leaf rows, (3) wide flat-topped canopy in sage green with stamped circles, (4) twin-trunk tree with two overlapping round canopies in olive and moss. Walnut-brown trunks with printed bark lines, each trunk ending in a straight flat bottom cut.", "any aspect ratio (square or landscape both acceptable)"),
    job("sh2_trees_warm_b", "a sheet of 4 separate NEW round-canopy autumn tree cards: (1) tall oval canopy in brick terracotta with printed leaf veins, (2) small round canopy in mustard ochre with stamped dots, (3) wide canopy mixing rust, ochre and olive leaf clusters, (4) slim young tree with a burnt-orange heart-shaped canopy. Walnut trunks, each ending in a straight flat bottom cut.", "any aspect ratio (square or landscape both acceptable)"),
    job("sh2_conifers_b", "a sheet of 6 separate NEW conifer cards of clearly different sizes: a very tall narrow dark fir, a medium round-tiered pine in olive, a small young fir, a pair of two firs on one base, a blue-grey spruce with snow-free drooping tiers, a short squat juniper. Printed needle hatching and stitched tier edges, each ending in a straight flat bottom cut."),
    job("sh2_foreground", "a sheet of 5 separate LARGE foreground plant cards (big, lush, detailed): a big fern clump with long curling fronds, a tall clump of meadow grass with feathery seed heads, a big dandelion clump with yellow flowers and two round seed clocks, a clump of broad burdock leaves with printed veins, a clump of tall foxtail grasses. Each grows from a straight flat bottom edge."),
    job("sh2_bush_flower_b", "a sheet of 8 separate small cards: a lavender clump, a purple thistle clump, a wild-rose bush with pink-cream roses, a low clover patch with white clover balls, a blue forget-me-not clump, a blackberry bush, a cluster of tiny white daisies in grass, a low round boxwood bush in dark green. Printed petals and leaf veins. Each grows from a straight flat bottom edge.", "any aspect ratio (square, portrait or landscape all acceptable)"),
    job("sh2_village_b", "a sheet of 2 separate village cottage cards, front-on: (1) a stone cottage with a moss-green roof, round grey printed stones, a terracotta door and warm glowing yellow windows, (2) a tiny round-topped cottage with an ochre thatched roof, a round window glowing warm yellow, a little porch and flower boxes. Each sits on a straight flat bottom edge, no ground, no path."),
    job("sh2_village_props_b", "a sheet of 6 separate village prop cards: a cluster of terracotta flower pots with flowers, a washing line between two posts with three plain cloths, an old iron water pump, a straw beehive skep on a small stand, a small wooden chicken coop, a wooden barrel. Printed wood grain, stitched lines, folk dots. Each with a straight flat bottom edge."),
    job("sh2_animals_b", "a sheet of 6 separate tiny decorative animal cards as simple folk-art silhouettes with printed patterns (dot or plain mark for an eye at most, no expressive faces): a brown hen, a white hen, a cream cow lying down with brown patches, a small grey rabbit sitting, two little ducklings, a black-and-white cat sitting seen from the back. Each with a straight flat bottom edge under the body.", "any aspect ratio (square, portrait or landscape all acceptable)"),
]

if __name__ == "__main__":
    p = f"{ROOT}/tools/art/jobs_cards_r2.json"
    json.dump(J, open(p, "w"), indent=1, ensure_ascii=False)
    print(len(J), "jobs ->", p)
